scanOpinion(summaryText, 'summary');
{
  const allowed = new Set([...happened.flatMap((it) => [...digitsOf(itemText(it))]), ...digitsOf(figures.map((f) => `${f.value} ${f.label}`).join(' ')), ...digitsOf(`${date} ${period.from} ${period.to}`)]);
